; flags.asm -- appendix I: chapter 2, question 4: two sums, A and F
; generated by genI.py
        INCLUDE "msx.inc"
        OUTPUT "flags.rom"
        ORG $4000
        CART_HEADER init
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off, no frame interrupt
        in a, (VDP_CTRL)        ; and none waiting
        ld a, 100
        add a, 100              ; 100 + 100
        push af
        pop hl
        ld ($C000), hl          ; F, then A
        ld a, 200
        sub 100                 ; 200 - 100
        push af
        pop hl
        ld ($C002), hl          ; F, then A
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
